:root {
  --bg-card: #fffdf7;
  --border-card: #e8dcc8;
  --header-bg: #6b3f1e;
  --header-text: #fff8ef;
  --badge-bg: #f0c97a;
  --badge-text: #5a3008;
  --col-heading: #7c4a1e;
  --ing-name: #3d2b1a;
  --ing-amount: #a0724a;
  --divider: #eddfc8;
  --hydration-track: #e8dcc8;
  --hydration-fill: #c27c3e;
  --hydration-text: #7c4a1e;
  --step-done-dot: #6b3f1e;
  --step-active-dot: #e08030;
  --step-pending-dot: #d6c5ae;
  --step-active-label: #c05a10;
  --step-pending-label: #b0967c;
  --step-done-label: #3d2b1a;
  --step-time: #a0724a;
  --footer-bg: #f5ebe0;
  --footer-label: #9a7050;
  --star-filled: #e8a020;
  --star-empty: #d6c5ae;
  --temp-value: #3d2b1a;
  --score-chip-bg: #6b3f1e;
  --score-chip-text: #fff8ef;
}

.bake-log {
  background: var(--bg-card);
  border: 1.5px solid var(--border-card);
  border-radius: 14px;
  width: 480px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.log-header {
  background: var(--header-bg);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.log-icon {
  font-size: 26px;
  line-height: 1;
}

.log-title {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
  color: var(--header-text);
  line-height: 1.2;
}

.log-date {
  margin: 0;
  font-size: 12px;
  color: var(--badge-bg);
  line-height: 1.3;
}

.batch-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}

.log-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.recipe-col {
  flex: 1;
  padding: 14px 16px;
  border-right: 1.5px solid var(--divider);
}

.timeline-col {
  flex: 1;
  padding: 14px 16px;
}

.col-heading {
  margin: 0 0 10px 0;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--col-heading);
}

.ingredient-list {
  list-style: none;
  margin: 0 0 12px 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ingredient {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
}

.ing-name {
  color: var(--ing-name);
  font-weight: 500;
}

.ing-amount {
  color: var(--ing-amount);
  font-weight: 600;
  font-size: 12px;
}

.hydration-bar-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}

.hydration-label {
  font-size: 11px;
  color: var(--hydration-text);
  font-weight: 600;
  white-space: nowrap;
}

.hydration-track {
  flex: 1;
  height: 7px;
  background: var(--hydration-track);
  border-radius: 4px;
  overflow: hidden;
}

.hydration-fill {
  width: 71%;
  height: 100%;
  background: var(--hydration-fill);
  border-radius: 4px;
}

.hydration-pct {
  font-size: 11px;
  font-weight: 700;
  color: var(--hydration-text);
}

.step-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.step {
  display: flex;
  align-items: center;
  gap: 8px;
}

.step-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--step-pending-dot);
  flex-shrink: 0;
}

.step.done .step-dot {
  background: var(--step-done-dot);
}

.step.active .step-dot {
  background: var(--step-active-dot);
  outline: 2.5px solid var(--step-active-dot);
  outline-offset: 2px;
}

.step-label {
  flex: 1;
  font-size: 13px;
  font-weight: 500;
  color: var(--step-pending-label);
}

.step.done .step-label {
  color: var(--step-done-label);
}

.step.active .step-label {
  color: var(--step-active-label);
  font-weight: 700;
}

.step-time {
  font-size: 11px;
  color: var(--step-time);
}

.log-footer {
  background: var(--footer-bg);
  border-top: 1.5px solid var(--divider);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 20px;
}

.crumb-rating {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.footer-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--footer-label);
}

.stars {
  display: flex;
  gap: 1px;
}

.star {
  font-size: 14px;
  color: var(--star-empty);
}

.star.filled {
  color: var(--star-filled);
}

.temp-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.temp-value {
  font-size: 15px;
  font-weight: 700;
  color: var(--temp-value);
}

.score-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.score-chip {
  background: var(--score-chip-bg);
  color: var(--score-chip-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
  display: inline-block;
}
